int handle_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;

    if (ctxt->mode == X86EMUL_MODE_REAL) {
        return inject_gpfault(ctxt, 0);
    }

    if (!ctxt->ops->get_msr(ctxt, MSR_EFER, &efer)) {
        return inject_ud(ctxt);
    }

    if (!(efer & EFER_SCE)) {
        return inject_ud(ctxt);
    }

    uint64_t cs_msr, eip_msr, esp_msr;

    if (!ctxt->ops->get_msr(ctxt, MSR_SYSENTER_CS, &cs_msr) ||
        !ctxt->ops->get_msr(ctxt, MSR_SYSENTER_EIP, &eip_msr) ||
        !ctxt->ops->get_msr(ctxt, MSR_SYSENTER_ESP, &esp_msr)) {
        return inject_gpfault(ctxt, 0);
    }

    if ((cs_msr & 0xff00) != 0x0000) {
        return inject_gpfault(ctxt, 0);
    }

    ctxt->regs->eip = (uint32_t)eip_msr;
    ctxt->regs->esp = (uint32_t)esp_msr;
    ctxt->regs->cs = (uint32_t)cs_msr;

    ctxt->eflags &= ~(X86_EFLAGS_VM | X86_EFLAGS_IOPL);
    ctxt->eflags |= (1 << 12); // IOPL=3

    return X86EMUL_CONTINUE;
}

int handle_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;

    /* Retrieve the EFER MSR */
    if (!ctxt->ops->get_msr(ctxt, MSR_EFER, &efer))
        return X86EMUL_UNHANDLEDMsr;

    /* Inject general protection fault if in real mode */
    if ((ctxt->mode & MODE_MASK) == MODE_REAL)
        return ctxt->ops->inject_gp(ctxt, 0);

    /* Check if SYSENTER is supported and valid */
    if (!(efer & EFER_SCE))
        return ctxt->ops->inject_ud(ctxt);

    /* Get SYSENTER CS, EIP, and ESP MSRs */
    uint32_t cs, eip, esp;
    if (!ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &cs) ||
        !ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &eip) ||
        !ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &esp))
        return X86EMUL_UNHANDLEDMsr;

    /* Update the emulation context's IP and SP */
    ctxt->eip = eip;
    ctxt->regs->esp = esp;
    ctxt->regs->cs = cs;

    return X86EMUL_CONTINUE;
}

int handle_sysexiter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;
    int rc;

    rc = get_msr(ctxt, MSR_EFER, &efer);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    if ((ctxt->mode == EMULATE_MODE_REAL) ||
        ((efer & EFER_LMA) && (ctxt->mode != EMULATE_MODE_PROT64))) {
        return inject_gp_fault(ctxt, 0);
    }

    if ((efer & EFER_SCE) == 0) {
        return inject_ud(ctxt);
    }

    uint64_t cs_msr, eip_msr, esp_msr;
    rc = get_msr(ctxt, MSR_IA32_SYSENTER_CS, &cs_msr);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &eip_msr);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &esp_msr);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    if (ctxt->mode == EMULATE_MODE_PROT64) {
        ctxt->regs->ip = eip_msr;
        ctxt->regs->sp = esp_msr;
        ctxt->regs->cs.selector = cs_msr;
    } else {
        ctxt->regs->ip = (uint32_t)eip_msr;
        ctxt->regs->sp = (uint32_t)esp_msr;
        ctxt->regs->cs.selector = (uint16_t)cs_msr;
    }

    return X86EMUL_CONTINUE;
}

int handle_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;

    /* Retrieve the EFER MSR */
    if (!ctxt->ops->get_msr(ctxt, MSR_EFER, &efer))
        return X86EMUL_UNHANDLEABLE;

    /* Check for real mode */
    if ((efer & (EFER_LMA | EFER_SCE)) != EFER_SCE)
        return X86EMUL_GPF;

    /* Check for undefined cases */
    if ((efer & EFER_LMA) && (ctxt->mode != X86EMUL_MODE_PROT64))
        return X86EMUL_UDF;

    uint64_t cs_msr, eip_msr, esp_msr;

    /* Retrieve SYSENTER CS, EIP, and ESP MSRs */
    if (!ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &cs_msr) ||
        !ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &eip_msr) ||
        !ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &esp_msr))
        return X86EMUL_UNHANDLEABLE;

    /* Set up the segments and the context */
    ctxt->regs->cs = cs_msr & 0xffff;
    ctxt->regs->ip = eip_msr;
    ctxt->regs->sp = esp_msr;

    /* Set the CPL to 0 */
    ctxt->regs->cs |= 0 << 3;

    return X86EMUL_CONTINUE;
}

int handle_sysenter(struct x86_emulate_ctxt *ctxt)
{
    uint64_t efer;

    if (ctxt->mode == X86EMUL_MODE_REAL) {
        return inject_gp_fault(ctxt, 0);
    }

    if (ctxt->op_size == 16) {
        return inject_ud_fault(ctxt);
    }

    efer = get_msr(ctxt, MSR_EFER);

    if (!(efer & EFER_SCE)) {
        return inject_ud_fault(ctxt);
    }

    if (ctxt->mode == X86EMUL_MODE_PROT) {
        ctxt->regs->cs = ctxt->regs->ss = get_msr(ctxt, MSR_IA32_SYSENTER_CS);
        ctxt->regs->ip = get_msr(ctxt, MSR_IA32_SYSENTER_EIP);
        ctxt->regs->sp = get_msr(ctxt, MSR_IA32_SYSENTER_ESP);
    } else {
        return inject_gp_fault(ctxt, 0);
    }

    return X86EMUL_CONTINUE;
}
